package com.pp.shaderlod.optimization.makeupspatial;
import org.lwjgl.opengl.*;import java.util.*;import com.pp.shaderlod.optimization.makeupprime.MakeUpDepthPriming;import net.irisshaders.iris.gl.IrisRenderSystem;
/** The existing native LEQUAL/invariant coverage contract, plus restoration of every2D unit touched by the derived program. */
public final class MakeUpSpatialState{
 public final MakeUpDepthPriming.State nativeState;private final int active;private final int[] images=new int[16],samplers=new int[16];private MakeUpSpatialState(MakeUpDepthPriming.State n){nativeState=n;active=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);try{for(int i=0;i<16;i++){GL13.glActiveTexture(GL13.GL_TEXTURE0+i);images[i]=GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D);samplers[i]=GL11.glGetInteger(GL33.GL_SAMPLER_BINDING);}}finally{GL13.glActiveTexture(active);}}
 public static MakeUpSpatialState capture(int program){var n=MakeUpDepthPriming.State.capture(program,false);if(n==null||GL11.glIsEnabled(GL11.GL_COLOR_LOGIC_OP))return null;var caps=GL.getCapabilities();if(!caps.OpenGL33)return null;if((GL11.glGetInteger(GL32.GL_CONTEXT_PROFILE_MASK)&GL32.GL_CONTEXT_CORE_PROFILE_BIT)==0&&GL11.glGetInteger(GL30.GL_CLAMP_FRAGMENT_COLOR)==GL11.GL_TRUE)return null;return new MakeUpSpatialState(n);}
 public void restore(){nativeState.restoreBindingsAndRaster();for(int i=0;i<16;i++){IrisRenderSystem.bindTextureToUnit(GL11.GL_TEXTURE_2D,i,images[i]);IrisRenderSystem.bindSamplerToUnit(i,samplers[i]);}GL13.glActiveTexture(active);}
 public void verify(int program){nativeState.assertRestored(program);int previous=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);try{for(int i=0;i<16;i++){GL13.glActiveTexture(GL13.GL_TEXTURE0+i);if(GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D)!=images[i]||GL11.glGetInteger(GL33.GL_SAMPLER_BINDING)!=samplers[i])throw new IllegalStateException("native spatial sampler restoration failed unit="+i);}}finally{GL13.glActiveTexture(previous);}if(previous!=active)throw new IllegalStateException("native active texture restoration failed");}
}
